INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8eeb68b9bcfa77ac7f52d7d2904b62c7ff052191/content/books/zizhi-tongjian/vol-287/year-0948/part-02/sources/library/jiuwudaishi-101-february-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002451；EPUB电子本，纸本及异文待核", "id": "55479174-0aeb-5890-957a-334fe5cada22"}, {"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8eeb68b9bcfa77ac7f52d7d2904b62c7ff052191/content/books/zizhi-tongjian/vol-287/year-0948/part-02/sources/library/jiuwudaishi-101-liu-chengyou-origin/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002450；EPUB电子本，纸本及异文待核", "id": "88df6c74-9b58-5d63-bca8-fcd8defaf83f"}, {"title": "旧五代史·卷一百〇九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8eeb68b9bcfa77ac7f52d7d2904b62c7ff052191/content/books/zizhi-tongjian/vol-287/year-0948/part-02/sources/library/jiuwudaishi-109-du-execution/source.txt", "note": "《旧五代史》卷一百〇九，段落 jiu-wudaishi-205deb4a7860-p002619；EPUB电子本，纸本及异文待核", "id": "8ee7efc1-c6a3-5f42-ab15-d900a4c321a6"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/81c86a2a7b16e48591c2de043347d16f153f6a6a/content/books/zizhi-tongjian/vol-287/year-0948/part-01/sources/library/tongjian-287-948-january-february/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003413；电子底本待考，分段待核", "id": "8d8704a9-dc0a-5afc-b382-8f7966c99bef"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/81c86a2a7b16e48591c2de043347d16f153f6a6a/content/books/zizhi-tongjian/vol-287/year-0948/part-01/sources/library/jiuwudaishi-100-january-948/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002444；EPUB电子本，纸本及异文待核", "id": "43740900-9a41-584e-b26c-37aecf88bcf1"}, {"title": "宋史·巻四百八十", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/81c86a2a7b16e48591c2de043347d16f153f6a6a/content/books/zizhi-tongjian/vol-287/year-0948/part-01/sources/library/songshi-480-xue-wen-protection/source.txt", "note": "《宋史》巻四百八十，段落 songshi-9c6e46fee832-p075054；EPUB电子本，纸本及异文待核", "id": "4e17c465-6a2c-5792-bf2e-14a6dd7414fe"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "刘信（刘知远从弟）", "aliases": ["劉信（劉知遠從弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的从弟，后汉将领。947年领义成节度使，兼侍卫马军都指挥使。与先前吴国将领刘信分别建档，生卒年尚未录入。", "biography": null, "status": "draft", "id": "a2f0a9f1-8401-5b6c-9a1e-3a49051af567"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "杜弘璋", "aliases": ["杜宏璋"], "era": "五代十国", "birth_year": null, "death_year": 948, "description": "杜重威之子。948年正月，后汉在刘知远去世后下诏处死杜重威父子，杜弘璋在被处斩者之列。《旧五代史》写作宏璋。出生年未载。", "biography": null, "status": "draft", "id": "0ccf12a4-73bb-5dc4-9451-de601a9dd9df"}, {"name": "杜弘琏", "aliases": ["杜弘璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杜重威之子。947年十一月乙亥出邺都见刘知远，参与父亲出降前的接洽。对应接洽在《旧五代史》杜重威传中写作宏遂，姓名差异保留；不与已录质子杜弘璲直接合并。生卒年尚未录入。", "biography": null, "status": "draft", "id": "dd9e1585-5674-5445-82b7-f38922a7afea"}, {"name": "杜弘璨", "aliases": ["杜宏璨"], "era": "五代十国", "birth_year": null, "death_year": 948, "description": "《资治通鉴》记为杜重威之子，948年正月与父亲及兄弟被后汉下诏处斩。《旧五代史》所列第三名儿子为宏杰，与弘璨是否同人尚待核，未直接合并。出生年未载。", "biography": null, "status": "draft", "id": "aded3202-c53b-50f5-a798-15cc2872e59e"}, {"name": "乐平长公主（杜重威妻）", "aliases": ["乐平长公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的妹妹、杜重威的妻子。937年的记载称她为乐平长公主。", "biography": null, "status": "draft", "id": "7cf58667-5bd6-58c5-8ebe-c3c1d463a473"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "庞福诚", "aliases": ["龐福誠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：庞福诚，太谷人、西川牙内指挥使、原屯来苏者。", "biography": null, "status": "draft", "id": "ad7796a7-b866-5eca-9f36-89b9a20e2a4b"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "白再荣", "aliases": ["白再榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋护圣都指挥使。944年二月甲辰朔奉命驻守马家口。原地名与石赟所守麻家口分别保留，不自动混写。生卒年本批未核。", "biography": null, "status": "draft", "id": "91caa219-2e64-565f-b15f-a4402d8c7b3d"}, {"name": "刘在明", "aliases": ["劉在明"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘在明，原戍易州将领。", "biography": null, "status": "draft", "id": "cb5c0d5f-5cf3-50c5-9e63-1b219aa861b0"}, {"name": "何承训", "aliases": ["何承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内牙指挥使。947年与钱弘倧商议驱逐胡进思，后来担忧事泄，反向胡进思告知谋议。与后汉皇子刘承训、霍彦威之子霍承训分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ed6fa1b8-f022-57b2-9729-421b42a24e17"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "薛温", "aliases": ["薛溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越匡武都头。948年正月奉钱弘俶命，率亲兵守护被废的钱弘倧，并受密令抵御异常处置。生卒年未载。", "biography": null, "status": "draft", "id": "adc72ad7-c8b7-5019-90f0-35e7952d1954"}, {"name": "方安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 948, "description": "胡进思的党羽。948年吴越政变后的记载中，与另一名未具姓名的人奉胡进思之命夜间越墙刺杀被废的钱弘倧，遭薛温率众杀死。行动的具体月日未载。", "biography": null, "status": "draft", "id": "b23cf10a-88c5-5b64-873e-3d9747f6cd50"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杨邠在刘知远病危时遣刘信赴镇", "start_year": 948, "end_year": 948, "time_original": "948年正月丁丑", "dynasty": "五代十国", "description": "刘知远病危时，杨邠忌惮侍卫马军都指挥使、忠武节度使刘信，立即遣他赴镇。刘信未能辞别皇帝，哭泣离去。", "phases": [], "location_name": "后汉朝廷至忠武军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "60578113-558f-51e5-a179-0f7bbf0a7fc8"}, {"title": "刘知远召四臣受顾命，托付刘承祐和后事", "start_year": 948, "end_year": 948, "time_original": "948年正月丁丑", "dynasty": "五代十国", "description": "刘知远召苏逢吉、杨邠、史弘肇、郭威接受顾命，表示自己气息微弱，不能多言，将年幼的刘承祐和后事托付给他们。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e9fb4136-c51c-5174-85e9-20734d36796f"}, {"title": "刘知远临终要求防备杜重威", "start_year": 948, "end_year": 948, "time_original": "948年正月丁丑", "dynasty": "五代十国", "description": "刘知远临终要求防备杜重威。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "51d8e227-ccf4-5d24-b8ee-eb7179cf231a"}, {"title": "刘知远在万岁殿去世", "start_year": 948, "end_year": 948, "time_original": "948年正月丁丑", "dynasty": "五代十国", "description": "刘知远在万岁殿去世。", "phases": [], "location_name": "万岁殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cd5920af-0372-5eec-a46b-6fb69fce5aa3"}, {"title": "苏逢吉等在刘知远死后暂不公布丧讯", "start_year": 948, "end_year": 948, "time_original": "948年正月丁丑刘知远去世后", "dynasty": "五代十国", "description": "苏逢吉等在刘知远死后暂不公布丧讯。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "678fc033-3911-5d7d-bd43-1446f83e714d"}, {"title": "后汉在刘知远死后下诏处斩杜重威父子", "start_year": 948, "end_year": 948, "time_original": "948年正月庚辰", "dynasty": "五代十国", "description": "刘知远去世、丧讯尚未公布时，后汉下诏称杜重威父子在皇帝小病期间诽谤朝廷、动摇人心，命处斩杜重威及弘璋、弘琏、弘璨，并不追究晋公主和内外亲族。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "72409546-d012-5bc6-a090-d55bbe4fffd0"}, {"title": "杜重威父子被处死", "start_year": 948, "end_year": 948, "time_original": "948年正月庚辰，执行据《旧五代史》补证", "dynasty": "五代十国", "description": "杜重威及其儿子被处死。《通鉴》列弘璋、弘琏、弘璨，《旧五代史》列宏璋、宏琏、宏杰，第三人的姓名差异尚待核。", "phases": [], "location_name": "后汉京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7b773d82-dd1b-5444-bdb2-14b92e077214"}, {"title": "杜重威尸体被陈列于市，遭市民争相撕食", "start_year": 948, "end_year": 948, "time_original": "948年正月庚辰处刑之后", "dynasty": "五代十国", "description": "杜重威的尸体被肢解陈列于市，市民争相食其肉，官吏无法制止，很快便被毁尽。", "phases": [], "location_name": "后汉京师市中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fc6e96b9-a103-5515-a2e1-f1a0bdafddbe"}, {"title": "刘承祐被封为周王、同平章事", "start_year": 948, "end_year": 948, "time_original": "948年二月辛巳朔", "dynasty": "五代十国", "description": "刘承祐被封为周王、同平章事。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e4f780d6-4c75-5c0e-9fdd-42d520badd95"}, {"title": "后汉公布刘知远丧讯与遗制，刘承祐继位", "start_year": 948, "end_year": 948, "time_original": "948年二月辛巳朔", "dynasty": "五代十国", "description": "刘承祐受封周王后不久，朝廷公布刘知远丧讯和遗制，命刘承祐即皇帝位。《资治通鉴》记刘承祐时年十八。", "phases": [], "location_name": "后汉宫廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c22ce8a4-f47d-50f8-b518-62ab03ede373"}, {"title": "韩保贞、庞福诚从陇州撤军，要求何重建一同西返", "start_year": 948, "end_year": 948, "time_original": "948年二月，抵秦州前，出发日未载", "dynasty": "五代十国", "description": "韩保贞、庞福诚从陇州撤军，要求何重建一同西返。", "phases": [], "location_name": "陇州至秦州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "09239f0f-d21f-596a-b2d5-2b79a79b47f3"}, {"title": "韩保贞等抵达秦州，分兵守门和道路，何重建入蜀", "start_year": 948, "end_year": 948, "time_original": "948年二月辛巳抵秦州，何重建入蜀具体日未另载", "dynasty": "五代十国", "description": "韩保贞等抵秦州，分兵守城门和道路，何重建随后进入蜀地。", "phases": [], "location_name": "秦州至蜀地", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fe3f2706-0754-59f4-a800-65ee4ad7acec"}, {"title": "刘承祐的母亲李氏被尊为皇太后", "start_year": 948, "end_year": 948, "time_original": "948年二月丁亥", "dynasty": "五代十国", "description": "刘承祐的母亲李氏被尊为皇太后。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e4220053-73d3-577a-af05-35529ba76e64"}, {"title": "后汉任命刘在明代替白再荣任成德留后", "start_year": 948, "end_year": 948, "time_original": "948年二月庚寅", "dynasty": "五代十国", "description": "后汉任命刘在明代替白再荣任成德留后。", "phases": [], "location_name": "成德军、镇州", "location_modern_name": null, "location_lat": null, "loca